INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Aliskiren', 'Benazepril', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ tăng kali máu, suy thận và hạ huyết áp', '1. Chống chỉ định ở bệnh nhân đái tháo đường hoặc suy thận (MLCT < 60 ml/ph/1,73 m²). 2. Ở các đối tượng khác, cũng nên tránh phối hợp này. Trong trường hợp bắt buộc phối hợp, theo dõi chặt chẽ kali, creatinin và huyết áp của bệnh nhân.');
