INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Alprazolam', 'Indinavir +/-ritonavir', 'Indinavir ức chế CYP3A4 làm giảm chuyển hóa của alprazolam', 'Tăng nồng độ alprazolam trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (buồn ngủ, lờ đờ, lẫn lộn, nặng hơn có thể xuất hiện mất điều hòa vận động, giảm trương lực cơ, hạ huyết áp, suy hô hấp, hôn mê)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Amiodaron', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
