INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Artemether/lu mefantrin', 'Phenobarbita l', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của artemether/lumef antrin', 'Giảm nồng độ của artemether/lumefan trin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Artemether/lu mefantrin', 'Phenytoin', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của artemether/lumef antrin', 'Giảm nồng độ của artemether/lumefan trin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Artemether/lu mefantrin', 'Sparfloxaci n', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Aspirin', 'Ketorolac', 'Hiệp đồng tác dụng kích ứng đường tiêu hóa', 'Tăng nguy cơ xuất huyết tiêu hóa nghiêm trọng (sử dụng đồng thời ketorolac với 1 NSAID khác làm tăng nguy cơ xuất huyết tiêu hóa gấp 5 lần so với phối hợp 2 NSAID khác)', 'Chống chỉ định phối hợp. Cần đặc biệt lưu ý nguy cơ tương tác trong trường hợp giảm đau hậu phẫu.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Lovastatin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của lovastatin', 'Tăng nồng độ của lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay lovastatin bằng các dẫn chất statin khác (ngoại trừ simvastatin), sử dụng liều thấp nhất có hiệu quả, atorvastatin không quá 10 mg/ngày, rosuvastatin không vượt quá 10 mg/ngày, pitavastatin không cần hiệu chỉnh liều khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Simvastatin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng các dẫn chất statin khác (ngoại trừ lovastatin) sử dụng liều thấp nhất có hiệu quả, atorvastatin không quá 10 mg/ngày, rosuvastatin không vượt quá 10 mg/ngày, pitavastatin không cần hiệu chỉnh liều khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Dihydroergot amin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của dihydroergotamin', 'Tăng nồng độ của dihydroergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Ergotamin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergotamin', 'Tăng nồng độ của ergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir', 'Ergometrin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng atazanavir, sử dụng ergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir', 'Methylergo metrin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của methylergometrin', 'Tăng nồng độ của methylergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng atazanavir, sử dụng methylergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Ivabradin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ivabradin', 'Tăng nồng độ ivabradin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT và chậm nhịp tim', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Ticagrelor', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ticagrelor', 'Tăng nồng độ của ticagrelor trong huyết thanh, tăng nguy cơ xuất huyết', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Ranolazin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ranolazin', 'Tăng nồng độ ranolazin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Tolvaptan', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của tolvaptan', 'Tăng nồng độ tolvaptan trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (tăng nồng độ natri huyết thanh, đa niệu, khát nước, giảm thể tích tuần hoàn...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Felodipin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của felodipin', 'Tăng nồng độ felodipin, tăng nguy cơ hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Lercanidipin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của lercanidipin', 'Tăng nồng độ lercanidipin, tăng nguy cơ hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir', 'Sildenafil', 'Atazanavir/ritona vir ức chế CYP3A4 làm giảm chuyển hóa của sildenafil', 'Tăng nồng độ sildenafil trong huyết thanh, tăng nguy cơ độc tính (hạ huyết áp, ngất, rối loạn thị giác)', '1. Chống chỉ định phối hợp trong trường hợp sử dụng sildenafil điều trị tăng áp động mạch phổi. 2. Trong trường hợp sử dụng sildenafil điều trị rối loạn cương dương, liều sildenafil không vượt quá 25 mg mỗi 48 giờ ở người đang sử dụng atazanavir.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir', 'Quetiapin', 'Atazanavir/ritona vir ức chế CYP3A4 mạnh làm giảm chuyển hóa của quetiapin', 'Tăng nồng độ của quetiapin, tăng nguy cơ kéo dài khoảng QT', 'Tốt nhất nên tránh phối hợp. Trong trường hợp bắt buộc sử dụng atazanavir, giảm liều quetiapin còn 1/6 liều so với liều bình thường.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của Atazanavir/ritona vir', 'Giảm nồng độ atazanavir trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Grazoprevir/ elbasvir', 'Atazanavir/ritona vir ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir', 'Domperidon', 'Atazanavir/ritona vir ức chế CYP3A4 làm giảm chuyển hóa của domperidon', 'Tăng nồng độ domperidon trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir (ritonavir)', 'Colchicin', 'Ritonavir ức chế mạnh CYP3A4 và ức chế P-gp làm giảm chuyển hóa và thải trừ colchicin.', 'Tăng nồng độ colchicin trong huyết thanh, tăng nguy cơ tác dụng độc tính (tiêu chảy, nôn, đau bụng, sốt, xuất huyết, giảm cả ba dòng tế bào máu, các dấu hiệu độc tính trên cơ như đau cơ, mỏi cơ hoặc yếu cơ, nước tiểu sẫm màu, dị cảm, trường hợp nặng có thể gây suy đa tạng và tử vong).', '1. Chống chỉ định ở bệnh nhân suy gan hoặc suy thận. 2. Ở bệnh nhân chức năng gan, thận bình thường: nên tránh phối hợp. Nếu phối hợp: giảm liều colchicin. Dùng liều tiếp theo của colchicin sau 3 ngày. Theo dõi nguy cơ độc tính của colchicin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir (ritonavir)', 'Vardenafil', 'Ritonavir ức chế CYP3A4 làm giảm chuyển hóa của vardenafil', 'Tăng nồng độ vardenafil trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir (ritonavir)', 'Propafenon', 'Ritonavir ức chế chuyển hóa của propafenon qua CYP3A4 và CYP2D6.', 'Tăng nồng độ, dẫn đến tăng độc tính của propafenon (đặc biệt là loạn nhịp tim).', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rito navir (ritonavir)', 'Everolimus', 'Ritonavir ức chế mạnh CP3A4 làm giảm chuyển hóa của everolimus ở gan, đồng thời, ức chế P-gp làm giảm thải trừ everolimus khỏi cơ thể.', 'Tăng nồng độ everolimus trong huyết thanh, tăng tác dụng bất lợi liên quan đến ức chế miễn dịch', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atazanavir/rit onavir (ritonavir)', 'Voriconazol', 'Ritonavir cảm ứng CYP2C19 (hoặc ức chế CYP3A4 ở người thiếu hoặc giảm hoạt tính CYP2C19) làm tăng (hoặc giảm) chuyển hóa của voriconazol tùy thuộc từng cá thể (voriconazol là cơ chất của cả CYP3A4 và CYP2C19)', 'Giảm (hoặc tăng) nồng độ voriconazol.', '1. Việc phối hợp voriconazol và ritonavir liều cao (400mg mỗi 12 giờ) làm giảm rõ rệt nồng độ voriconazol, vì vậy, chống chỉ định phối hợp voriconazol với ritonavir ở mức liều này. 2. Việc phối hợp voriconazol với ritonavir liều thấp (100mg mỗi 12 giờ) cũng đã cho thấy làm giảm nồng độ voriconazol mặc dù mức độ ít hơn so với liều cao ritonavir, vì vậy, nên tránh phối hợp thuốc trừ khi lợi ích vượt trội nguy cơ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atorvastatin', 'Ciclosporin', 'Ciclosporin ức chế CYP3A4 làm giảm chuyển hóa của atorvastatin; ciclosporin cũng ức chế cả OATP1B1 làm giảm vận chuyển atorvastatin vào gan.', 'Tăng nồng độ simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: thay atorvastatin bằng fluvastatin (tối đa 20 mg/ngày), pravastatin (tối đa 20 mg/ngày), rosuvastatin (tối đa 5 mg/ngày).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atorvastatin', 'Gemfibrozil', 'Gemfibrozil ức chế OATP1B1 làm giảm vận chuyển atorvastatin vào gan.', 'Tăng nồng độ atorvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất fibrat, thay thế gemfibrozil bằng fenofibrat nhưng cần thận trọng khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Atropin', 'Kali clorid (dạng uống giải phóng kéo dài)', 'Atropin kháng cholinergic gây tồn lưu hoặc làm tăng thời gian kali qua đường tiêu hóa khi sử dụng đường uống, gây loét đường tiêu hóa', 'Tăng nguy cơ loét tiêu hóa', '1. Tốt nhất nên tránh phối hợp, đặc biệt ở người cao tuổi. Cân nhắc chuyển sang sử dụng kali đường tĩnh mạch. 2. Trong trường hợp bắt buộc sử dụng đồng thời, cân nhắc một số khuyến cáo sau giúp giảm nguy cơ loét tiêu hóa: (1) uống ít nhất 100 mL nước sau khi uống kali, (2) ngồi hoặc đứng thẳng trong ít nhất 5 - 10 phút sau khi uống thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Azithromycin', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Azithromycin', 'Haloperidol', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Azithromycin', 'Sparfloxaci n', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Azithromycin', 'Domperidon', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Benazepril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng benazepril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bleomycin', 'Brentuximab', 'Chưa rõ', 'Tăng nguy cơ độc tính (không nhiễm trùng) trên phổi (bao gồm viêm phổi không nhiễm trùng, bệnh phổi kẽ hoặc hội chứng suy hô hấp cấp tính (ARDS) do tổn thương phế nang, với biểu hiện khó thở, ho và sốt không đặc hiệu', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Lovastatin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của lovastatin', 'Tăng nồng độ của lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Simvastatin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Colchicin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của colchicin', 'Tăng nồng độ colchicin trong huyết thanh, tăng nguy cơ tác dụng độc tính (tiêu chảy, nôn, đau bụng, sốt, xuất huyết, giảm cả ba dòng tế bào máu, các dấu hiệu độc tính trên cơ như đau cơ, mỏi cơ hoặc yếu cơ, nước tiểu sẫm màu, dị cảm, trường hợp nặng có thể gây suy đa tạng và tử vong).', '1. Chống chỉ định ở bệnh nhân suy gan hoặc suy thận. 2. Ở bệnh nhân chức năng gan, thận bình thường: nên tránh phối hợp. Nếu phối hợp: giảm liều colchicin. Dùng liều tiếp theo của colchicin sau 3 ngày. Theo dõi nguy cơ độc tính của colchicin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Dihydroergot amin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của dihydroergotamin', 'Tăng nồng độ của dihydroergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Ergotamin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergotamin', 'Tăng nồng độ của ergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Ergometrin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Methylergo metrin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của methylergometrin', 'Tăng nồng độ của methylergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Boceprevir', 'Ivabradin', 'Boceprevir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ivabradin', 'Tăng nồng độ ivabradin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT và chậm nhịp tim', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bosentan', 'Glibenclami d', 'Bosentan cảm ứng CYP3A4 và CYP2C9, làm tăng chuyển hóa của glibenclamid. Cơ chế tăng enzym gan chưa rõ', 'Tăng nguy cơ tăng enzym gan, giảm nồng độ glibenclamid trong huyết thanh,giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bosentan', 'Ciclosporin', 'Ciclosporin ức chế CYP3A4 làm giảm chuyển hóa của bosentan; bosentan cảm ứng CYP3A4 làm tăng chuyển hóa của ciclosporin', 'Tăng nồng độ của bosentan, tăng nguy cơ tác dụng không mong muốn (đau đầu..); giảm nồng độ của ciclosporin trong huyết thanh, giảm hiệu quả điều trị, tăng nguy cơ thải ghép', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Brivudin', 'Capecitabin', 'Chất chuyển hóa của brivudin ức chế enzym dihydropyrimidin e dehydrogenase (DPD) - enzym chuyển hóa capecitabin', 'Tăng nồng độ capecitabin trong máu, dẫn đến tăng nguy cơ độc tính', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng capecitabin sau khi ngừng brivudin ít nhất 4 tuần.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Brivudin', 'Fluorouracil', 'Chất chuyển hóa của brivudin ức chế enzym dihydropyrimidin e dehydrogenase (DPD) - enzym chuyển hóa fluorouracil', 'Tăng nồng độ fluoruoracil trong máu, dẫn đến tăng nguy cơ độc tính', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng fluoruoracil sau khi ngừng brivudin ít nhất 4 tuần.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Brivudin', 'Tegafur', 'Chất chuyển hóa của brivudin ức chế enzym dihydropyrimidin e dehydrogenase (DPD) - enzym chuyển hóa tegafur', 'Tăng nồng độ tegafur trong máu, dẫn đến tăng nguy cơ độc tính', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng tegafur sau khi ngừng brivudin ít nhất 4 tuần.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bromocriptin', 'Metoclopram id', 'Đối kháng tác dụng của nhau', 'Giảm hiệu quả của cả hai thuốc', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bromocriptin', 'Sulpirid', 'Đối kháng tác dụng của nhau', 'Giảm hiệu quả của cả hai thuốc', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bupropion', 'Linezolid', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời linezolid và bupropion. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng linezolid và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bupropion', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời xanh methylen và bupropion. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng xanh methylen và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Bupropion', 'Furazolidon', 'Hiệp đồng tác dụng serotonin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời furazolidon và bupropion. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng furazolidon và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Calci clorid', 'Ceftriaxon', 'Hình thành tủa calci - ceftriaxon tại mô phổi và thận khi dùng đồng thời đường tĩnh mạch ở trẻ sơ sinh', 'Tạo kết tủa tại phổi và thận, có thể dẫn đến tử vong ở trẻ sơ sinh', '1. Chống chỉ định sử dụng đồng thời ở trẻ sơ sinh (< 28 ngày tuổi). 2. Ở các đối tượng khác, không trộn lẫn calci và ceftriaxon trong cùng 1 đường truyền, dùng 2 thuốc theo 2 đường truyền tại 2 vị trí khác nhau hoặc dùng lần lượt từng thuốc sau đó khi tráng rửa đường truyền bằng dung môi tương hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Calci glubionat', 'Ceftriaxon', 'Hình thành tủa calci - ceftriaxon tại mô phổi và thận khi dùng đồng thời đường tĩnh mạch ở trẻ sơ sinh', 'Tạo kết tủa tại phổi và thận, có thể dẫn đến tử vong ở trẻ sơ sinh', '1. Chống chỉ định sử dụng đồng thời ở trẻ sơ sinh (< 28 ngày tuổi). 2. Ở các đối tượng khác, không trộn lẫn calci và ceftriaxon trong cùng 1 đường truyền, dùng 2 thuốc theo 2 đường truyền tại 2 vị trí khác nhau hoặc dùng lần lượt từng thuốc sau đó khi tráng rửa đường truyền bằng dung môi tương hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Calci gluconat', 'Ceftriaxon', 'Hình thành tủa calci - ceftriaxon tại mô phổi và thận khi dùng đồng thời đường tĩnh mạch ở trẻ sơ sinh', 'Tạo kết tủa tại phổi và thận, có thể dẫn đến tử vong ở trẻ sơ sinh', '1. Chống chỉ định sử dụng đồng thời ở trẻ sơ sinh (< 28 ngày tuổi). 2. Ở các đối tượng khác, không trộn lẫn calci và ceftriaxon trong cùng 1 đường truyền, dùng 2 thuốc theo 2 đường truyền tại 2 vị trí khác nhau hoặc dùng lần lượt từng thuốc sau đó khi tráng rửa đường truyền bằng dung môi tương hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Captopril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng captopril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepi n', 'Linezolid', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời linezolid và carbamazepin. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng linezolid và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
