INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Praziquantel', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của praziquantel', 'Giảm nồng độ của praziquantel trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Rilpivirin', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Voriconazol', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của voriconazol', 'Giảm nồng độ của voriconazol trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Daclatasvir', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của daclatasvir', 'Giảm nồng độ của daclatasvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Delamanid', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của delamanid', 'Giảm nồng độ của delamanid trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Grazoprevir/ elbasvir', 'Carbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của Grazoprevir/elbas vir', 'Giảm nồng độ grazoprevir/elbasvi r trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepin', 'Ranolazin', 'Carbamazepin cảm ứng CYP3A4 và P-gp làm tăng chuyển hóa của ranolazin và thải trừ của ranolazin.', 'Giảm nồng độ ranolazin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carbamazepi n', 'Furazolidon', 'Hiệp đồng tác dụng serotonin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời furazolidon và carbamazepin. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng furazolidon và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Carvedilol', 'Colchicin', 'Carvedilol ức chế P-gp làm giảm thải trừ colchicin.', 'Tăng nồng độ colchicin trong huyết thanh, tăng nguy cơ tác dụng độc tính (tiêu chảy, nôn, đau bụng, sốt, xuất huyết, giảm cả ba dòng tế bào máu, các dấu hiệu độc tính trên cơ như đau cơ, mỏi cơ hoặc yếu cơ, nước tiểu sẫm màu, dị cảm, trường hợp nặng có thể gây suy đa tạng và tử vong).', '1. Chống chỉ định ở bệnh nhân suy gan hoặc suy thận. 2. Ở bệnh nhân chức năng gan, thận bình thường: nên tránh phối hợp. Nếu phối hợp: giảm liều colchicin. Dùng liều tiếp theo của colchicin sau 3 ngày. Theo dõi nguy cơ độc tính của colchicin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ceftriaxon', 'Dung dịch nuôi dưỡng đường tĩnh mạch chứa calci', 'Hình thành tủa calci - ceftriaxon tại mô phổi và thận khi dùng đồng thời đường tĩnh mạch ở trẻ sơ sinh', 'Tạo kết tủa tại phổi và thận, có thể dẫn đến tử vong ở trẻ sơ sinh', '1. Chống chỉ định sử dụng đồng thời ở trẻ sơ sinh (< 28 ngày tuổi). 2. Ở các đối tượng khác, không trộn lẫn calci và ceftriaxon trong cùng 1 đường truyền, dùng 2 thuốc theo 2 đường truyền tại 2 vị trí khác nhau hoặc dùng lần lượt từng thuốc sau đó khi tráng rửa đường truyền bằng dung môi tương hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ceftriaxon', 'Ringer Lactat', 'Hình thành tủa calci - ceftriaxon tại mô phổi và thận khi dùng đồng thời đường tĩnh mạch ở trẻ sơ sinh', 'Tạo kết tủa tại phổi và thận, có thể dẫn đến tử vong ở trẻ sơ sinh', '1. Chống chỉ định sử dụng đồng thời ở trẻ sơ sinh (< 28 ngày tuổi). 2. Ở các đối tượng khác, không trộn lẫn calci và ceftriaxon trong cùng 1 đường truyền, dùng 2 thuốc theo 2 đường truyền tại 2 vị trí khác nhau hoặc dùng lần lượt từng thuốc sau đó khi tráng rửa đường truyền bằng dung môi tương hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Celecoxib', 'Ketorolac', 'Hiệp đồng tác dụng kích ứng đường tiêu hóa', 'Tăng nguy cơ xuất huyết tiêu hóa nghiêm trọng (sử dụng đồng thời ketorolac với 1 NSAID khác làm tăng nguy cơ xuất huyết tiêu hóa gấp 5 lần so với phối hợp 2 NSAID khác)', 'Chống chỉ định phối hợp. Cần đặc biệt lưu ý nguy cơ tương tác trong trường hợp giảm đau hậu phẫu.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Pitavastatin', 'Ciclosporin ức chế OATP1B1 làm giảm vận chuyển pitavastatin vào gan.', 'Tăng nồng độ pitavastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: thay pitavastatin bằng fluvastatin (tối đa 20 mg/ngày), pravastatin (tối đa 20 mg/ngày), rosuvastatin (tối đa 5 mg/ngày).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Lovastatin', 'Ciclosporin ức chế CYP3A4 làm giảm chuyển hóa của lovastatin; ciclosporin cũng ức chế cả OATP1B1 làm giảm vận chuyển lovastatin vào gan.', 'Tăng nồng độ lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay lovastatin bằng fluvastatin (tối đa 20 mg/ngày), pravastatin (tối đa 20 mg/ngày), rosuvastatin (tối đa 5 mg/ngày).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Simvastatin', 'Ciclosporin ức chế CYP3A4 làm giảm chuyển hóa của simvastatin; ciclosporin cũng ức chế cả OATP1B1 làm giảm vận chuyển simvastatin vào gan.', 'Tăng nồng độ simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng fluvastatin (tối đa 20 mg/ngày), pravastatin (tối đa 20 mg/ngày), rosuvastatin (tối đa 5 mg/ngày).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Colchicin', 'Ciclosporin ức chế P-gp làm giảm thải trừ colchicin.', 'Tăng nồng độ colchicin trong huyết thanh, tăng nguy cơ tác dụng độc tính (tiêu chảy, nôn, đau bụng, sốt, xuất huyết, giảm cả ba dòng tế bào máu, các dấu hiệu độc tính trên cơ như đau cơ, mỏi cơ hoặc yếu cơ, nước tiểu sẫm màu, dị cảm, trường hợp nặng có thể gây suy đa tạng và tử vong).', '1. Chống chỉ định ở bệnh nhân suy gan hoặc suy thận. 2. Ở bệnh nhân chức năng gan, thận bình thường: nên tránh phối hợp. Nếu phối hợp: giảm liều colchicin. Dùng liều tiếp theo của colchicin sau 3 ngày. Theo dõi nguy cơ độc tính của colchicin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Lercanidipin', 'Ciclosporin ức chế CYP3A4 làm giảm chuyển hóa của lercanidipin và ngược lại, lercanidipin ức chế yếu CYP3A4 làm giảm chuyển hóa ciclosporin.', 'Tăng nồng độ ciclosporin, tăng nồng độ lercanidipin trong huyết thanh, tăng nguy cơ hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciclosporin', 'Grazoprevir/ elbasvir', 'Ciclosporin ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Cilostazol', 'Domperidon', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciprofloxacin', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciprofloxacin', 'Tizanidin', 'Ciprofloxacin ức chế CYP1A2 mạnh làm giảm chuyển hóa của tizanidin', 'Tăng nồng độ của tizanidin trong huyết thanh, tăng nguy cơ tác dụng bất lợi (hạ huyết áp, buồn ngủ, nhịp tim chậm...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciprofloxacin', 'Duloxetin', 'Ciprofloxacin ức chế CYP1A2 mạnh làm giảm chuyển hóa của duloxetin', 'Tăng nồng độ của duloxetin trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (buồn ngủ, hôn mê, hội chứng serotonin, co giật, nôn và nhịp tim nhanh...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ciprofloxacin', 'Domperidon', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', 'Chống chỉ định phối hợp.');
