INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dabigatran', 'Itraconazol', 'Itraconazol ức chế P-gp làm giảm thải trừ dabigatran khỏi cơ thể', 'Tăng nồng độ dabigatran trong huyết thanh, tăng nguy cơ xuất huyết', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Daclatasvir', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của daclatasvir', 'Giảm nồng độ của daclatasvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Daclatasvir', 'Enzalutamid', 'Enzalutamid cảm ứng CYP3A4 làm tăng chuyển hóa của daclatasvir', 'Giảm nồng độ của daclatasvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Daclatasvir', 'Phenobarbita l', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của daclatasvir', 'Giảm nồng độ của daclatasvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Daclatasvir', 'Phenytoin', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của daclatasvir', 'Giảm nồng độ của daclatasvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Danazol', 'Simvastatin', 'Danazol ức chế CYP3A4 làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Danazol', 'Lovastatin', 'Danazol ức chế CYP3A4 làm giảm chuyển hóa của lovastatin', 'Tăng nồng độ lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Lovastatin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của lovastatin', 'Tăng nồng độ của lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay lovastatin bằng các dẫn chất statin khác (ngoại trừ simvastatin), sử dụng liều thấp nhất có hiệu quả, atorvastatin không vượt quá 20 mg/ngày (hoặc 40 mg/ngày theo Hướng dẫn điều trị HIV/AIDS của Bộ Y tế và Tổ chức Y tế Thế giới), pitavastatin không cần hiệu chỉnh liều khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Simvastatin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng các dẫn chất statin khác (ngoại trừ lovastatin), sử dụng liều thấp nhất có hiệu quả, atorvastatin không vượt quá 20 mg/ngày (hoặc 40 mg/ngày theo Hướng dẫn điều trị HIV/AIDS của Bộ Y tế và Tổ chức Y tế Thế giới), pitavastatin không cần hiệu chỉnh liều khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Dihydroergot amin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của dihydroergotamin', 'Tăng nồng độ của dihydroergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Ergotamin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergotamin', 'Tăng nồng độ của ergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rit onavir', 'Ergometrin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng darunavir, sử dụng ergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rit onavir', 'Methylergo metrin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của methylergometrin', 'Tăng nồng độ của methylergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng darunavir, sử dụng methylergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Ivabradin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ivabradin', 'Tăng nồng độ ivabradin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT và chậm nhịp tim', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Ticagrelor', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ticagrelor', 'Tăng nồng độ của ticagrelor trong huyết thanh, tăng nguy cơ xuất huyết', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Ranolazin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ranolazin', 'Tăng nồng độ ranolazin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Tolvaptan', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của tolvaptan', 'Tăng nồng độ tolvaptan trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (tăng nồng độ natri huyết thanh, đa niệu, khát nước, giảm thể tích tuần hoàn...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Felodipin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của felodipin', 'Tăng nồng độ felodipin, tăng nguy cơ hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Lercanidipin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của lercanidipin', 'Tăng nồng độ lercanidipin, tăng nguy cơ hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rit onavir', 'Sildenafil', 'Darunavir/ritonav ir ức chế CYP3A4 làm giảm chuyển hóa của sildenafil', 'Tăng nồng độ sildenafil trong huyết thanh, tăng nguy cơ độc tính (hạ huyết áp, ngất, rối loạn thị giác)', '1. Chống chỉ định phối hợp trong trường hợp sử dụng sildenafil điều trị tăng áp động mạch phổi. 2. Trong trường hợp sử dụng sildenafil điều trị rối loạn cương dương, liều sildenafil không vượt quá 25 mg mỗi 48 giờ ở người đang sử dụng darunavir.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rit onavir', 'Quetiapin', 'Darunavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của quetiapin', 'Tăng nồng độ của quetiapin, tăng nguy cơ kéo dài khoảng QT', 'Tốt nhất nên tránh phối hợp. Trong trường hợp bắt buộc sử dụng darunavir, giảm liều quetiapin còn 1/6 liều so với liều bình thường.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của Darunavir/ritonav ir', 'Giảm nồng độ darunavir trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Grazoprevir/ elbasvir', 'Darunavir/ritonav ir ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir', 'Domperidon', 'Darunavir/ritonav ir ức chế CYP3A4 làm giảm chuyển hóa của domperidon', 'Tăng nồng độ domperidon trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir (ritonavir)', 'Vardenafil', 'Ritonavir ức chế CYP3A4 làm giảm chuyển hóa của vardenafil', 'Tăng nồng độ vardenafil trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir (ritonavir)', 'Propafenon', 'Ritonavir ức chế chuyển hóa của propafenon qua CYP3A4 và CYP2D6.', 'Tăng nồng độ, dẫn đến tăng độc tính của propafenon (đặc biệt là loạn nhịp tim).', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rito navir (ritonavir)', 'Everolimus', 'Ritonavir ức chế mạnh CP3A4 làm giảm chuyển hóa của everolimus ở gan, đồng thời, ức chế P-gp làm giảm thải trừ everolimus khỏi cơ thể.', 'Tăng nồng độ everolimus trong huyết thanh, tăng tác dụng bất lợi liên quan đến ức chế miễn dịch', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Darunavir/rit onavir (ritonavir)', 'Voriconazol', 'Ritonavir cảm ứng CYP2C19 (hoặc ức chế CYP3A4 ở người thiếu hoặc giảm hoạt tính CYP2C19) làm tăng (hoặc giảm) chuyển hóa của voriconazol tùy thuộc từng cá thể (voriconazol là cơ chất của cả CYP3A4 và CYP2C19)', 'Giảm (hoặc tăng) nồng độ voriconazol.', '1. Việc phối hợp voriconazol và ritonavir liều cao (400mg mỗi 12 giờ) làm giảm rõ rệt nồng độ voriconazol, vì vậy, chống chỉ định phối hợp voriconazol với ritonavir ở mức liều này. 2. Việc phối hợp voriconazol với ritonavir liều thấp (100mg mỗi 12 giờ) cũng đã cho thấy làm giảm nồng độ voriconazol mặc dù mức độ ít hơn so với liều cao ritonavir, vì vậy, nên tránh phối hợp thuốc trừ khi lợi ích vượt trội nguy cơ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Delamanid', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của delamanid', 'Giảm nồng độ của delamanid trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Delamanid', 'Enzalutamid', 'Enzalutamid cảm ứng CYP3A4 làm tăng chuyển hóa của delamanid', 'Giảm nồng độ của delamanid trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Delamanid', 'Phenytoin', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của delamanid', 'Giảm nồng độ của delamanid trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dexamethason', 'Rilpivirin', 'Dexamethason cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dexibuprofen', 'Ketorolac', 'Hiệp đồng tác dụng kích ứng đường tiêu hóa', 'Tăng nguy cơ xuất huyết tiêu hóa nghiêm trọng (sử dụng đồng thời ketorolac với 1 NSAID khác làm tăng nguy cơ xuất huyết tiêu hóa gấp 5 lần so với phối hợp 2 NSAID khác)', 'Chống chỉ định phối hợp. Cần đặc biệt lưu ý nguy cơ tương tác trong trường hợp giảm đau hậu phẫu.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dexketoprofen', 'Ketorolac', 'Hiệp đồng tác dụng kích ứng đường tiêu hóa', 'Tăng nguy cơ xuất huyết tiêu hóa nghiêm trọng (sử dụng đồng thời ketorolac với 1 NSAID khác làm tăng nguy cơ xuất huyết tiêu hóa gấp 5 lần so với phối hợp 2 NSAID khác)', 'Chống chỉ định phối hợp. Cần đặc biệt lưu ý nguy cơ tương tác trong trường hợp giảm đau hậu phẫu.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dexlansoprazo l', 'Rilpivirin', 'Giảm hấp thu rilpivirin do tăng pH dạ dày', 'Giảm nồng độ rilpivirin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp thay thế bằng thuốc kháng H2, sử dụng các thuốc H2 ít nhất 12 giờ trước hoặc 4 giờ sau khi uống rilpivirin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dextromethor phan', 'Linezolid', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời linezolid và dextromethorphan. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (codein) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng linezolid và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dextromethor phan', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời xanh methylen và dextromethorphan. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (codein) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng xanh methylen và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dextromethorp han', 'Paroxetin', 'Paroxetin ức chế CYP2D6 làm giảm chuyển hóa của dextromethorpha n', 'Tăng nồng độ dextromethorphan, tăng nguy cơ độc tính (nôn, buồn nôn, nhìn mờ, ảo giác) hoặc tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dextromethorp han', 'Fluoxetin', 'Fluoxetin ức chế CYP2D6 làm giảm chuyển hóa của dextromethorpha n', 'Tăng nồng độ dextromethorphan, tăng nguy cơ độc tính (nôn, buồn nôn, nhìn mờ, ảo giác) hoặc tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dextromethor phan', 'Furazolidon', 'Hiệp đồng tác dụng serotonin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời furazolidon và dextromethorphan. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (codein) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng furazolidon và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Diclofenac', 'Ketorolac', 'Hiệp đồng tác dụng kích ứng đường tiêu hóa', 'Tăng nguy cơ xuất huyết tiêu hóa nghiêm trọng (sử dụng đồng thời ketorolac với 1 NSAID khác làm tăng nguy cơ xuất huyết tiêu hóa gấp 5 lần so với phối hợp 2 NSAID khác)', 'Chống chỉ định phối hợp. Cần đặc biệt lưu ý nguy cơ tương tác trong trường hợp giảm đau hậu phẫu.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dicycloverin', 'Kali clorid (dạng thuốc viên sử dụng đường uống)', 'Dicycloverin kháng cholinergic gây tồn lưu hoặc làm tăng thời gian kali qua đường tiêu hóa khi sử dụng đường uống, gây loét đường tiêu hóa', 'Tăng nguy cơ loét đường tiêu hóa', '1. Tốt nhất nên tránh phối hợp, đặc biệt ở người cao tuổi. Cân nhắc chuyển sang sử dụng kali đường tĩnh mạch. 2. Trong trường hợp bắt buộc sử dụng đồng thời, cân nhắc một số khuyến cáo sau giúp giảm nguy cơ loét tiêu hóa: (1) uống ít nhất 100 mL nước sau khi uống kali, (2) ngồi hoặc đứng thẳng trong ít nhất 5 - 10 phút sau khi uống thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dihydroergota min', 'Sumatriptan', 'Hiệp đồng tác dụng co mạch', 'Co thắt mạch kéo dài', 'Chống chỉ định phối hợp. Hai thuốc cách nhau ít nhất 24 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Dihydroergota min', 'Roxithromyc in', 'Roxithromycin ức chế CYP3A4 mạnh làm giảm chuyển hóa của dihydroergotamin', 'Tăng nồng độ của dihydroergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
