INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Duloxetin', 'Fluvoxamin', 'Fluvoxamin ức chế CYP1A2 mạnh làm giảm chuyển hóa của duloxetin', 'Tăng nồng độ của duloxetin trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (buồn ngủ, hôn mê, hội chứng serotonin, co giật, nôn và nhịp tim nhanh...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Duloxetin', 'Furazolidon', 'Hiệp đồng tác dụng serotonin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời furazolidon và duloxetin. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng furazolidon và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Efavirenz', 'Grazoprevir/ elbasvir', 'Efavirenz cảm ứng CYP3A4 làm tăng chuyển hóa của Grazoprevir/elbas vir', 'Giảm nồng độ grazoprevir/elbasvi r trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Efavirenz', 'Voriconazol', 'Efavirenz cảm ứng CYP3A4 làm tăng chuyển hóa của voriconazol; voriconazol ức chế CYP3A4 làm giảm chuyển hóa của efavirenz', 'Giảm nồng độ voriconazol, tăng nồng độ efavirenz trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', '1. Chống chỉ định với liều efavirenz trên 400 mg/ngày. 2. Voriconazol có thể phối hợp efavirenz khi tăng liều duy trì của voriconazol lên 400 mg mỗi 12 giờ và giảm liều của efavirenz còn 300 mg mỗi 24 giờ. Khi ngừng sử dụng voriconazol, có thể quay lại sử dụng liều ban đầu efavirenz.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Eltrombopag', 'Grazoprevir/ elbasvir', 'Eltrombopag ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Enalapril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng enalapril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Enzalutamid', 'Grazoprevir/ elbasvir', 'Enzalutamid cảm ứng CYP3A4 làm tăng chuyển hóa của Grazoprevir/elbas vir', 'Giảm nồng độ grazoprevir/elbasvi r trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ephedrin (sử dụng đường uống)', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Tăng tích lũy noradrenalin (norepinephrin)', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', '1. Chống chỉ định sử dụng ephedrin sử dụng đường uống đồng thời hoặc trong vòng 14 ngày trước đó có sử dụng linezolid. 2. Đối với ephedrin sử dụng đường tiêm, cần sử dụng rất thận trọng trên bệnh nhân đang dùng linezolid trong điều kiện giám sát huyết áp chặt chẽ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ephedrin (sử dụng đường uống)', 'Xanh methylen (sử dụng đường', 'Tăng tích lũy noradrenalin (norepinephrin)', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh', '1. Chống chỉ định sử dụng ephedrin sử dụng đường uống đồng thời hoặc trong vòng 14');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ephedrin (sử dụng đường uống)', 'Furazolidon', 'Tăng tích lũy noradrenalin (norepinephrin). Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', '1. Chống chỉ định sử dụng ephedrin sử dụng đường uống đồng thời hoặc trong vòng 14 ngày trước đó có sử dụng furazolidon. 2. Đối với ephedrin sử dụng đường tiêm, cần sử dụng rất thận trọng trên bệnh nhân đang dùng furazolidon trong điều kiện giám sát huyết áp chặt chẽ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Sumatriptan', 'Hiệp đồng tác dụng co mạch', 'Co thắt mạch kéo dài', 'Chống chỉ định phối hợp. Hai thuốc cách nhau ít nhất 24 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Roxithromyc in', 'Roxithromycin ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Erythromyci n', 'Erythromycin ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Voriconazol', 'Voriconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Posaconazol', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Itraconazol', 'Itraconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Saquinavir +/- ritonavir', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng saquinavir, sử dụng ergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Lopinavir/ri tonavir', 'Lopinavir/ritonav ir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng lopinavir/ritonavir, sử dụng ergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergometrin', 'Indinavir +/- ritonavir', 'Indinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergometrin', 'Tăng nồng độ của ergometrin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Tốt nhất nên tránh phối hợp. Đối với trường hợp điều trị băng huyết sau sinh, nếu không còn thuốc khác thay thế ở người bệnh đang sử dụng indinavir, sử dụng ergometrin chỉ khi lợi ích vượt trội nguy cơ và sử dụng liều thấp nhất có hiệu quả trong thời gian ngắn nhất.');
