INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ergotamin', 'Roxithromyc in', 'Roxithromycin ức chế CYP3A4 mạnh làm giảm chuyển hóa của ergotamin', 'Tăng nồng độ của ergotamin trong huyết thanh, tăng nguy cơ độc tính (nôn, buồn nôn, hoại tử đầu chi, thiếu máu cục bộ do co thắt mạch…)', 'Chống chỉ định phối hợp');
