INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Fluvoxamin', 'Tizanidin', 'Fluvoxamin ức chế CYP1A2 mạnh làm giảm chuyển hóa của tizanidin', 'Tăng nồng độ của tizanidin trong huyết thanh, tăng nguy cơ tác dụng bất lợi (hạ huyết áp, buồn ngủ, nhịp tim chậm...)', 'Chống chỉ định phối hợp');
