INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Methadon', 'Hiệp đồng tác dụng serotonin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời furazolidon và methadon. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (morphin, codein, oxycodon, buprenorphin) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng furazolidon và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Levodopa/ca rbidopa +/-entacapon', 'Tăng tích lũy noradrenalin (norepinephrin) và dopamin. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', 'Chống chỉ định sử dụng levodopa/carbidopa đồng thời hoặc trong vòng 14 ngày gần đây có sử dụng furazolidon.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Methyldopa', 'Chưa rõ', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Pseudoephed rin (sử dụng đường uống)', 'Tăng tích lũy noradrenalin (norepinephrin). Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', 'Chống chỉ định sử dụng pseudoephedrin (sử dụng đường uống) đồng thời hoặc trong vòng 14 ngày gần đây có sử dụng furazolidon.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Phenylephrin (sử dụng đường uống)', 'Tăng tích lũy noradrenalin (norepinephrin). Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày.', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', '1. Chống chỉ định sử dụng phenylephrin sử dụng đường uống đồng thời hoặc trong vòng 14 ngày trước đó có sử dụng furazolidon. 2. Đối với phenylephrin sử dụng đường tiêm, cần sử dụng rất thận trọng trên bệnh nhân đang dùng furazolidon trong điều kiện giám sát huyết áp chặt chẽ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Furazolidon', 'Nefopam', 'Nefopam ức chế thu hồi noradrenalin (norepinephrin) và serotonin trên hệ thần kinh. Tác dụng ức chế MAO của furazolidon do chất chuyển hóa của thuốc, xuất hiện chậm sau 5 - 10 ngày', 'Tăng nguy cơ kích thích thần kinh trung ương (co giật, ảo giác và kích động)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Gemfibrozil', 'Repaglinid', 'Gemfibrozil ức chế CYP2C8 làm giảm chuyển hóa của repaglinid, gemfibrozil cũng ức chế OATP1B1 làm giảm vận chuyển gemfibrozil vào gan.', 'Tăng nồng độ repaglinid trong huyết thanh, tăng nguy cơ hạ đường huyết', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Gemfibrozil', 'Simvastatin', 'Gemfibrozil ức chế OATP1B1 làm giảm vận chuyển simvastatin vào gan.', 'Tăng nồng độ simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất fibrat, thay thế gemfibrozil bằng fenofibrat nhưng cần thận trọng khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Gemfibrozil', 'Lovastatin', 'Gemfibrozil ức chế OATP1B1 làm giảm vận chuyển lovastatin vào gan.', 'Tăng nồng độ lovastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất fibrat, thay thế gemfibrozil bằng fenofibrat nhưng cần thận trọng khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Gemfibrozil', 'Pravastatin', 'Gemfibrozil ức chế OATP1B1 làm giảm vận chuyển pravastatin vào gan.', 'Tăng nồng độ pravastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất fibrat, thay thế gemfibrozil bằng fenofibrat nhưng cần thận trọng khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Grazoprevir/el basvir', 'Phenobarbita l', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của Grazoprevir/elbas vir', 'Giảm nồng độ grazoprevir/elbasvi r trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Grazoprevir/el basvir', 'Phenytoin', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của Grazoprevir/elbas vir', 'Giảm nồng độ grazoprevir/elbasvi r trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Grazoprevir/el basvir', 'Rifampicin', 'Rifampicin ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan. Khi dùng rifampicin dài ngày, rifampicin gây cảm ứng CYP3A4 làm giảm nồng độ rifampicin trong huyết thanh.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT. Khi dùng rifampicin dài ngày, lại có nguy cơ giảm nồng độ grazoprevir/elbasvi r, giảm hiệu quả điều trị.', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Grazoprevir/el basvir', 'Saquinavir +/- ritonavir', 'Saquinavir ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Grazoprevir/el basvir', 'Lopinavir/rit onavir (lopinavir)', 'Lopinavir ức chế OATP1B1/3 làm giảm vận chuyển grazoprevir vào gan.', 'Tăng nồng độ grazoprevir/elbasvi r, tăng nguy cơ tăng ALT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Haloperidol', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
