INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Irinotecan', 'Itraconazol', 'Itraconazol ức chế CYP3A4 và ức chế UGT1A1 (enzym xúc tác phản ứng glucuronid hóa) làm giảm chuyển hóa của SN-38 (chất chuyển hóa có hoạt tính của irinotecan)', 'Tăng nồng độ của chất chuyển hóa có hoạt tính của irinotecan trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (tiêu chảy, giảm bạch cầu trung tính...)', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng irinotecan sau khi ngừng itraconazol ít nhất 2 tuần.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Isosorbid dinitrat', 'Sildenafil', 'Hiệp đồng tăng nồng độ guanosine monophosphate (cGMP) vòng có dụng giãn mạch', 'Tăng tác dụng hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp. Hai thuốc cách nhau ít nhất 24 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Isosorbid dinitrat', 'Vardenafil', 'Hiệp đồng tăng nồng độ guanosine monophosphate (cGMP) vòng có dụng giãn mạch', 'Tăng tác dụng hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp. Hai thuốc cách nhau ít nhất 24 giờ.');
