INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Nefopam', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Nefopam ức chế thu hồi noradrenalin (norepinephrin) và serotonin trên hệ thần kinh', 'Tăng nguy cơ kích thích thần kinh trung ương (co giật, ảo giác và kích động)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Nicoradil', 'Sildenafil', 'Hiệp đồng tăng nồng độ guanosine monophosphate (cGMP) vòng có dụng giãn mạch', 'Tăng tác dụng hạ huyết áp nghiêm trọng', 'Chống chỉ định phối hợp. Hai thuốc cách nhau ít nhất 24 giờ.');
