INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Esomeprazol', 'Rilpivirin', 'Giảm hấp thu rilpivirin do tăng pH dạ dày', 'Giảm nồng độ rilpivirin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp thay thế bằng thuốc kháng H2, sử dụng các thuốc H2 ít nhất 12 giờ trước hoặc 4 giờ sau khi uống rilpivirin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Omeprazol', 'Rilpivirin', 'Giảm hấp thu rilpivirin do tăng pH dạ dày', 'Giảm nồng độ rilpivirin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp thay thế bằng thuốc kháng H2, sử dụng các thuốc H2 ít nhất 12 giờ trước hoặc 4 giờ sau khi uống rilpivirin.');
