INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Oxaliplatin', 'Sparfloxaci n', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Oxcarbamazep in', 'Rilpivirin', 'Oxcarbamazepin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Pantoprazol', 'Rilpivirin', 'Giảm hấp thu rilpivirin do tăng pH dạ dày', 'Giảm nồng độ rilpivirin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp thay thế bằng thuốc kháng H2, sử dụng các thuốc H2 ít nhất 12 giờ trước hoặc 4 giờ sau khi uống rilpivirin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Paroxetin', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời xanh methylen và tramadol. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (morphin, codein, oxycodon, buprenorphin) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng xanh methylen và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Paroxetin', 'Thioridazin', 'Paroxetin ức chế CYP2D6 làm giảm chuyển hóa của thioridazin', 'Tăng nồng độ thioridazin, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Peginterferon-alpha (2a hoặc 2b)', 'Telbivudin', 'Chưa rõ', 'Tăng nguy cơ viêm thần kinh ngoại vi liên quan đến telbivudin.', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Perindopril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng perindopril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Pethidin', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời xanh methylen và pethidin. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. Trong trường hợp bắt buộc sử dụng opioid, có thể đổi sang các opiod khác không có hoạt tính ức chế thu hồi serotonin (morphin, codein, oxycodon, buprenorphin) 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng xanh methylen và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenobarbital', 'Praziquantel', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của praziquantel', 'Giảm nồng độ của praziquantel trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenobarbital', 'Rilpivirin', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenobarbital', 'Voriconazol', 'Phenobarbital cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của voriconazol', 'Giảm nồng độ của voriconazol trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenobarbital', 'Ranolazin', 'Phenobarbital cảm ứng CYP3A4 và P-gp làm tăng chuyển hóa của ranolazin và thải trừ của ranolazin.', 'Giảm nồng độ ranolazin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenylephrin (sử dụng đường uống)', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Tăng tích lũy noradrenalin (norepinephrin)', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', '1. Chống chỉ định sử dụng phenylephrin sử dụng đường uống đồng thời hoặc trong vòng 14 ngày trước đó có sử dụng xanh methylen. 2. Đối với phenylephrin sử dụng đường tiêm, cần sử dụng rất thận trọng trên bệnh nhân đang dùng xanh methylen trong điều kiện giám sát huyết áp chặt chẽ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenytoin', 'Praziquantel', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của praziquantel', 'Giảm nồng độ của praziquantel trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenytoin', 'Rilpivirin', 'Phenytoin cảm ứng CYP3A4 mạnh làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Phenytoin', 'Ranolazin', 'Phenytoin cảm ứng CYP3A4 và P-gp làm tăng chuyển hóa của ranolazin và thải trừ của ranolazin.', 'Giảm nồng độ ranolazin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Piperaquin/di hydroartemisi nin (piperaquin)', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Piperaquin/di hydroartemisi nin (piperaquin)', 'Sotalol', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Piperaquin/di hydroartemisi nin (piperaquin)', 'Saquinavir +/- ritonavir', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Piperaquin/di hydroartemisi nin (piperaquin)', 'Sparfloxaci n', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Piribedil', 'Sulpirid', 'Đối kháng tác dụng của nhau', 'Giảm hiệu quả của cả hai thuốc', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Posaconazol', 'Simvastatin', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: - Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay posaconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4) HOẶC - Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng các dẫn chất statin khác (ngoại trừ lovastatin).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Posaconazol', 'Ticagrelor', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ticagrelor', 'Tăng nồng độ của ticagrelor trong huyết thanh, tăng nguy cơ xuất huyết', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay posaconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Posaconazol', 'Ranolazin', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ranolazin', 'Tăng nồng độ ranolazin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay posaconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Posaconazol', 'Tolvaptan', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của tolvaptan', 'Tăng nồng độ tolvaptan trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (tăng nồng độ natri huyết thanh, đa niệu, khát nước, giảm thể tích tuần hoàn...)', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay posaconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Posaconazol', 'Quetiapin', 'Posaconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của quetiapin', 'Tăng nồng độ của quetiapin, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay posaconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Pramipexol', 'Sulpirid', 'Đối kháng tác dụng của nhau', 'Giảm hiệu quả của cả hai thuốc', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Praziquantel', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của praziquantel', 'Giảm nồng độ của praziquantel trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Với rifampicin, chỉ bắt đầu sử dụng praziquantel sau khi ngừng rifampicin ít nhất 4 tuần. Rifampicin có thể sử dụng lại sau 1 ngày dừng praziquantel.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Propafenon', 'Saquinavir/ri tonavir (ritonavir)', 'Ritonavir ức chế chuyển hóa của propafenon qua CYP3A4 và CYP2D6.', 'Tăng nồng độ, dẫn đến tăng độc tính của propafenon (đặc biệt là loạn nhịp tim).', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Pseudoephedri n (sử dụng đường uống)', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Tăng tích lũy noradrenalin (norepinephrin)', 'Tăng nguy cơ xuất hiện cơn tăng huyết áp (đau đầu, đánh trống ngực, cứng cổ, tăng huyết áp)', 'Chống chỉ định sử dụng pseudoephedrin (sử dụng đường uống) đồng thời hoặc trong vòng 14 ngày trước đó có sử dụng xanh methylen.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Quetiapin', 'Saquinavir +/- ritonavir', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của quetiapin', 'Tăng nồng độ của quetiapin, tăng nguy cơ kéo dài khoảng QT', 'Tốt nhất nên tránh phối hợp. Trong trường hợp bắt buộc sử dụng saquinavir, giảm liều quetiapin còn 1/6 liều so với liều bình thường.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Quetiapin', 'Voriconazol', 'Voriconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của quetiapin', 'Tăng nồng độ của quetiapin, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay voriconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Quinapril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng quinapril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rabeprazol', 'Rilpivirin', 'Giảm hấp thu rilpivirin do tăng pH dạ dày', 'Giảm nồng độ rilpivirin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp thay thế bằng thuốc kháng H2, sử dụng các thuốc H2 ít nhất 12 giờ trước hoặc 4 giờ sau khi uống rilpivirin.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ramipril', 'Sacubitril/val sartan (sacubitril)', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng ramipril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ranolazin', 'Saquinavir +/- ritonavir', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ranolazin', 'Tăng nồng độ ranolazin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ranolazin', 'Voriconazol', 'Voriconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của ranolazin', 'Tăng nồng độ ranolazin trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay voriconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Ranolazin', 'Rifampicin', 'Rifampicin cảm ứng CYP3A4 và P-gp làm tăng chuyển hóa của ranolazin và thải trừ của ranolazin.', 'Giảm nồng độ ranolazin trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rifampicin', 'Rilpivirin', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của rilpivirin', 'Giảm nồng độ của rilpivirin trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rifampicin', 'Voriconazol', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của voriconazol', 'Giảm nồng độ của voriconazol trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng voriconazol, cân nhắc thay đổi phác đồ chống lao cho bệnh nhân.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rifampicin', 'Sofosbuvir', 'Rifampicin cảm ứng P-gp làm tăng thải trừ của sofusbuvir', 'Giảm nồng độ của sofosbuvir trong huyết thanh, dẫn đến giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rifampicin', 'Saquinavir +/- ritonavir', 'Rifampicin cảm ứng CYP3A4 làm tăng chuyển hóa của saquinavir', 'Giảm nồng độ saquinavir trong huyết thanh, giảm hiệu quả điều trị', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rosuvastatin', 'Sofosbuvir/le dipasvir (ledipasvir)', 'Ledipasvir ức chế BCRP và P-gp làm giảm thải trừ rosuvastatin khỏi cơ thể', 'Tăng nồng độ rosuvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Rotigotin', 'Sulpirid', 'Đối kháng tác dụng của nhau', 'Giảm hiệu quả của cả hai thuốc', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sacubitril/vals artan (sacubitril)', 'Trandolapril', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng trandolapril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sacubitril/vals artan (sacubitril)', 'Zofenopril', 'Tăng tích lũy bradykinin gây phù mạch', 'Tăng nguy cơ phù mạch', 'Chống chỉ định phối hợp. Chỉ bắt đầu sử dụng Sacubitril/valsartan (sacubitril) sau khi ngừng zofenopril ít nhất 36 giờ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir +/-ritonavir', 'Simvastatin', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng các dẫn chất statin khác (ngoại trừ lovastatin) sử dụng liều thấp nhất có hiệu quả, atorvastatin không vượt quá 20 mg/ngày, pitavastatin và pravastatin không cần hiệu chỉnh liều khi phối hợp.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir +/-ritonavir', 'Ticagrelor', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của ticagrelor', 'Tăng nồng độ của ticagrelor trong huyết thanh, tăng nguy cơ xuất huyết', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir +/-ritonavir', 'Tolvaptan', 'Saquinavir ức chế CYP3A4 mạnh làm giảm chuyển hóa của tolvaptan', 'Tăng nồng độ tolvaptan trong huyết thanh, tăng nguy cơ tác dụng không mong muốn (tăng nồng độ natri huyết thanh, đa niệu, khát nước, giảm thể tích tuần hoàn...)', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir +/-ritonavir', 'Sildenafil', 'Saquinavir ức chế CYP3A4 làm giảm chuyển hóa của sildenafil', 'Tăng nồng độ sildenafil trong huyết thanh, tăng nguy cơ độc tính (hạ huyết áp, ngất, rối loạn thị giác)', '1. Chống chỉ định phối hợp trong trường hợp sử dụng sildenafil điều trị tăng áp động mạch phổi. 2. Trong trường hợp sử dụng sildenafil điều trị rối loạn cương dương, liều sildenafil không vượt quá 25 mg mỗi 48 giờ ở người đang sử dụng saquinavir.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir/rito navir (ritonavir)', 'Vardenafil', 'Ritonavir ức chế CYP3A4 làm giảm chuyển hóa của vardenafil', 'Tăng nồng độ vardenafil trong huyết thanh, tăng nguy cơ kéo dài khoảng QT', 'Chống chỉ định phối hợp');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Saquinavir/rit onavir (ritonavir)', 'Voriconazol', 'Ritonavir cảm ứng CYP2C19 (hoặc ức chế CYP3A4 ở người thiếu hoặc giảm hoạt tính CYP2C19) làm tăng (hoặc giảm) chuyển hóa của voriconazol tùy thuộc từng cá thể (voriconazol là cơ chất của cả CYP3A4 và CYP2C19)', 'Giảm (hoặc tăng) nồng độ voriconazol.', '1. Việc phối hợp voriconazol và ritonavir liều cao (400mg mỗi 12 giờ) làm giảm rõ rệt nồng độ voriconazol, vì vậy, chống chỉ định phối hợp voriconazol với ritonavir ở mức liều này. 2. Việc phối hợp voriconazol với ritonavir liều thấp (100mg mỗi 12 giờ) cũng đã cho thấy làm giảm nồng độ voriconazol mặc dù mức độ ít hơn so với liều cao ritonavir, vì vậy, nên tránh phối hợp thuốc trừ khi lợi ích vượt trội nguy cơ.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sertralin', 'Xanh methylen (sử dụng đường tiêm tĩnh mạch)', 'Hiệp đồng tác dụng serotonin', 'Tăng nguy cơ hội chứng serotonin (sốt cao, rối loạn nhận thức, tăng phản xạ, mất phối hợp, rung giật cơ, cứng cơ, co giật, nhịp tim nhanh, tăng huyết áp, tăng thân nhiệt, vã mồ hôi, ảo giác, kích động hoặc bồn chồn…)', '1. Cố gắng tránh sử dụng đồng thời xanh methylen và doxylamin. Tốt nhất các thuốc này nên sử dụng cách nhau 2 tuần. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn. 2. Trong hợp không thể trì hoãn điều trị được 2 tuần, bắt buộc sử dụng dài ngày hoặc khẩn cấp bằng xanh methylen và không có thuốc khác thay thế, cân bằng lợi ích và nguy cơ xảy ra hội chứng serotonin. Nếu lợi ích vượt trội nguy cơ, vẫn có thể sử dụng đồng thời nhưng cần giám sát chặt chẽ chặt chẽ bệnh nhân, đặc biệt trong tháng đầu tiên sử dụng đồng thời 2 thuốc.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sevofluran', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sevofluran', 'Sparfloxaci n', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Simvastatin', 'Voriconazol', 'Voriconazol ức chế CYP3A4 mạnh làm giảm chuyển hóa của simvastatin', 'Tăng nồng độ của simvastatin trong huyết thanh, tăng nguy cơ bệnh cơ hoặc tiêu cơ vân cấp', 'Chống chỉ định phối hợp. Cân nhắc thay đổi sang các thuốc nhóm khác có cùng chỉ định và ít có nguy cơ tương tác hơn: - Trong trường hợp bắt buộc sử dụng thuốc kháng nấm azol, thay voriconazol bằng fluconazol (nhưng tránh dùng liều cao, có tác dụng ức chế mạnh CYP3A4) HOẶC - Trong trường hợp bắt buộc sử dụng dẫn chất statin, thay simvastatin bằng các dẫn chất statin khác (ngoại trừ lovastatin).');
INSERT INTO drug_interaction (active_element_1, active_element_2, mechanism, consequence, management) VALUES ('Sotalol', 'Thioridazin', 'Hiệp đồng tăng tác dụng', 'Tăng nguy cơ kéo dài khoảng QT, xoắn đỉnh', '1. Chống chỉ định phối hợp ở các bệnh nhân có hội chứng QT kéo dài do di truyền hoặc mắc phải. 2. Trên các đối tượng bệnh nhân khác, tốt nhất nên tránh phối hợp các thuốc này. Trong trường hợp cần thiết phối hợp, cần đánh giá cẩn thận nguy cơ/lợi ích và lượng giá các yếu tố nguy cơ trên từng bệnh nhân, đặc biệt là rối loạn điện giải (hạ kali máu, hạ magie máu, hạ calci máu), nhịp tim chậm, nữ giới trước khi quyết định kê đơn.');
